import{_ as s,o as r,c as t,a3 as a}from"./chunks/framework.I6s8z2kk.js";const m=JSON.parse('{"title":"Horses","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/horses.md","filePath":"user/center/horses.md"}'),o={name:"user/center/horses.md"};function n(i,e,h,l,d,c){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="horses" tabindex="-1">Horses <a class="header-anchor" href="#horses" aria-label="Permalink to &quot;Horses&quot;">​</a></h1><p>Keep a list of the horses at your center under <strong>Horses</strong>. You need the <em>Manage horses</em> permission.</p><p>Each horse has:</p><ul><li>a <strong>name</strong></li><li>a <strong>room</strong> number (several horses can share a room)</li><li>a <strong>photo</strong> (optional)</li><li>an <strong>owner</strong>: either your center, or one of your clients</li></ul><h2 id="adding-a-horse" tabindex="-1">Adding a horse <a class="header-anchor" href="#adding-a-horse" aria-label="Permalink to &quot;Adding a horse&quot;">​</a></h2><p>Click <strong>New</strong>, enter the name and room, and add a photo if you want. To record a client&#39;s horse, pick the client as the owner. If that client isn&#39;t in your client list yet, they&#39;re added to it. Leave the owner empty for a horse your center owns.</p><h2 id="finding-and-editing-horses" tabindex="-1">Finding and editing horses <a class="header-anchor" href="#finding-and-editing-horses" aria-label="Permalink to &quot;Finding and editing horses&quot;">​</a></h2><p>Filter the list to show only your center&#39;s horses or only clients&#39; horses, show the horses of one client, or search by name. When you edit a horse you can change its name, room, photo or owner. Clearing the owner makes the horse your center&#39;s.</p><h2 id="assigning-trainers" tabindex="-1">Assigning trainers <a class="header-anchor" href="#assigning-trainers" aria-label="Permalink to &quot;Assigning trainers&quot;">​</a></h2><p>Open a horse and choose the <strong>trainers</strong> who work with it. A horse can have several trainers, and a trainer can work with several horses. Save the full list each time; removing a trainer from the list unlinks them. You can also filter the horse list to one trainer&#39;s horses.</p><h2 id="horses-and-stays" tabindex="-1">Horses and stays <a class="header-anchor" href="#horses-and-stays" aria-label="Permalink to &quot;Horses and stays&quot;">​</a></h2><p>The <strong>Horses and stays</strong> view shows, in one list:</p><ul><li>every horse that is <strong>stabled right now</strong> (a confirmed stay that has started), with its service, end date, status and how many payments are still to collect for the stay and its invoices;</li><li>every other horse, with its owner and trainers.</li></ul><p>Switch between <strong>All</strong>, <strong>Active stays</strong> and <strong>Others</strong>, and search by horse name, client name or phone. You need the horses or the reservations permission.</p><p>Open a stay to see its details (dates, price, extras, payment, the horse with its owner and trainers) and every invoice billed during it with its payment status. Ended and cancelled stays can be opened too.</p><h2 id="removing-a-horse" tabindex="-1">Removing a horse <a class="header-anchor" href="#removing-a-horse" aria-label="Permalink to &quot;Removing a horse&quot;">​</a></h2><p>Deleting a horse removes it from the list.</p>',17)])])}const p=s(o,[["render",n]]);export{m as __pageData,p as default};
